def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos_list(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def safe_get(d, k, default=None):
        try:
            return d.get(k, default)
        except Exception:
            return default

    def choose_best(points, s, mode="near"):
        best = None
        best_score = None
        for p in points or []:
            p = pos_list(p)
            if p is None:
                continue
            sc = dist(s, p)
            if mode == "far":
                sc = -sc
            if best is None or sc < best_score:
                best = p
                best_score = sc
        return best

    env = safe_get(observation, "environment_name", "resource_collection")
    sx_sy = pos_list(safe_get(observation, "self_position", None))
    if sx_sy is None:
        sx_sy = [0, 0]
    sx, sy = sx_sy[0], sx_sy[1]

    ox_oy = pos_list(safe_get(observation, "opponent_position", None))
    if ox_oy is None:
        ox_oy = [sx, sy]

    gw = safe_get(observation, "grid_width", None)
    gh = safe_get(observation, "grid_height", None)
    center = [gw // 2, gh // 2] if isinstance(gw, int) and isinstance(gh, int) and gw > 0 and gh > 0 else [sx, sy]

    role = safe_get(observation, "self_role", "pursuer")

    if env == "pursuit_evasion":
        if role == "pursuer":
            move = step_toward(sx_sy, ox_oy)
            if move == [0, 0]:
                move = [0, 1]
            return move
        corners = []
        if isinstance(gw, int) and isinstance(gh, int) and gw > 0 and gh > 0:
            corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
        else:
            corners = [[-10, -10], [-10, 10], [10, -10], [10, 10]]
        target = choose_best(corners, ox_oy, mode="far")
        if target is None:
            target = center
        move = step_toward(sx_sy, target)
        if move == [0, 0]:
            move = step_away(sx_sy, ox_oy)
        return move

    if env == "territory_control":
        targets = safe_get(observation, "unclaimed_cells", None)
        if not targets:
            targets = safe_get(observation, "opponent_territory", None)
        if not targets:
            targets = safe_get(observation, "neutral_cells", None)
        target = choose_best(targets, sx_sy, mode="near")
        if target is None:
            target = center if center != [sx, sy] else ox_oy
        move = step_toward(sx_sy, target)
        if move == [0, 0]:
            move = step_toward(sx_sy, center)
        return move

    resources = safe_get(observation, "resources", None)
    if not resources:
        resources = safe_get(observation, "resource_positions", None)
    enemy_threat = dist(sx_sy, ox_oy)

    if resources:
        if enemy_threat <= 2:
            target = choose_best(resources, ox_oy, mode="far")
            move = step_away(sx_sy, ox_oy)
            if target is not None and dist(sx_sy, target) > dist(sx_sy, ox_oy):
                move = step_toward(sx_sy, target)
            return move
        target = choose_best(resources, sx_sy, mode="near")
        if target is not None:
            return step_toward(sx_sy, target)

    if enemy_threat <= 1:
        move = step_away(sx_sy, ox_oy)
        if move == [0, 0]:
            move = [1, 0]
        return move

    move = step_toward(sx_sy, center)
    if move == [0, 0]:
        move = step_toward(sx_sy, ox_oy)
    return move

